/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-09: new module - the reload of the flows after a change in storage
 *   (watchFlows of the storage plugin, preReload hook, deploy.reload settings)
 *   Z-09: review fixes - a strict read of storage (getFlows({strict: true})); a
 *   superseded cycle checks the revision in storage again (no lost reload);
 *   after the retries were exhausted storage is read every retry.max; one retry
 *   timer, timers unref, waits ended by stop()
 *   Z-16: health.unreadyGrace - after /ready turned 503 the flows are not
 *   reloaded before the grace has passed (in parallel with the preReload hook)
 *   #1 (R-47): deploy.reload.retry.onExhausted "keepReady" and maxStaleTime - after
 *   the retries were exhausted a ready instance stays ready on the running
 *   revision; the condition `reload` of the instance state, error logs, an
 *   editor notification and the stale timer report it
 *   #17: the failures are counted until the cycle succeeds (the reload applied
 *   or the revision unchanged), not until the first read succeeds - a failed
 *   reread under the lock or a failed reload step exhausts retry.attempts too;
 *   a notification resets the retry delay, not the count; a new series after a
 *   recovery by a local deployment is counted again
 *   #26: a new series after a recovery resets the counters explicitly; a
 *   successful cycle cancels the retry scheduled by an earlier failure, also when
 *   its timer fired during that cycle (retryQueued, apart from `pending`); a retry
 *   that fired during a failing cycle does not bypass the backoff
 *   #2: the credentials are compared like the flow revision (the digest of the
 *   decrypted content, flows.credentialsChanged): the `credentialsChanged` of a
 *   notification is only a hint to read storage, `credentialsChanged` of the
 *   preReload payload is computed
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The reload of the flows after a change in storage (Z-09, contract E-01
 * part B - design/engine-extensions/ZASADY.md §2.3).
 *
 * Enabled with `deploy.reload.watch: true` and a storage plugin that provides
 * the optional `watchFlows(callback)`. Without either the module does nothing
 * (the behaviour of the base version).
 *
 * ```js
 * deploy: {
 *     reload: {
 *         watch: false,              // observe storage (watchFlows)
 *         type: "full",              // "full" | "diff" - restart all or only the changed flows
 *         preReloadTimeout: 1200000, // limit of the preReload hook (drain), ms
 *         concurrency: 1,            // optional: reloads at the same time in the cluster (Z-10 slots)
 *         retry: {                   // failed reload cycles (read, reread, reload)
 *             min: 1000, max: 60000, attempts: 10,
 *             onExhausted: "fail",   // "fail" | "keepReady" - after the attempts (R-47)
 *             maxStaleTime: 1800000  // ms, with "keepReady": /ready 503 after it; 0 - no limit
 *         }
 *     }
 * }
 * ```
 *
 * After `retry.attempts` failed cycles in a row the instance state is `failed`
 * (R-36, `/ready` 503) and storage is read again every `retry.max`. A cycle fails
 * at any step - the read of step 2, the reread under the lock or the reload
 * itself (#17); the count starts again only after a cycle succeeded (the reload
 * was applied or storage holds the running revision). With
 * `onExhausted: "keepReady"` and a read error of storage (`storage_error`) the
 * lifecycle state is NOT changed - a ready instance stays ready on the running
 * revision (`/ready` 200 `warn`, see health.js) - and the condition `reload`
 * of the instance state is set (R-47); errors of the configuration
 * (`credentials_load_failed`, `invalid_flows`, `invalid_json`, `empty_file`, any
 * other) always give `failed`. With the default `"fail"` no condition is set and
 * nothing is reported beyond what R-36 did before.
 * The condition is reported actively: an error log on entering and (at most once
 * per `retry.max`) while it lasts, the retained editor notification
 * `reload-failed` (a message that disappears on recovery), the event
 * `instance:state`, and an error log, an event and an updated notification when
 * `maxStaleTime` (counted from the first failed read) passes (`/ready` 503). It
 * ends when storage is read with the running revision (nothing to reload), a
 * reload or a local deployment succeeded.
 *
 * One cycle:
 *  1. a notification - while a cycle runs, notifications are coalesced into
 *     one following cycle; before the end of the first start of the flows they
 *     are buffered
 *  2. storage is read (no lock); the same revision as the active one and the same
 *     credentials (the digest of the decrypted content, not the ciphertext) -
 *     nothing to do (an own write or a duplicate); a change of the credentials
 *     alone is a reload (always a full one). The `credentialsChanged` flag of a
 *     notification only starts this read, it neither forces nor prevents a reload
 *  3. instance state "reloadPending" (no lock); with `concurrency` a reload
 *     slot is claimed through the coordination (`/ready` unchanged while waiting)
 *  4. "draining" (`/ready` 503): the `preReload` hook, at most `preReloadTimeout`;
 *     with `health.unreadyGrace` (and `health.enabled`) the reload also waits
 *     until that many ms have passed since the drain started (`/ready` answers
 *     503 at the latest) - at the same time as the hook, so the wait is the
 *     longer of the two, and at most `preReloadTimeout`; a deployment on this instance or a stop ends it;
 *     a deployment (or POST /flows/state) on this instance in steps 3-4 supersedes
 *     the reload; one more cycle then compares the revision in storage with the
 *     active one (a failed deployment saved nothing)
 *  5. under the deploy lock: storage is read again (the newest revision) and
 *     the configuration is reloaded ("reloading") - nothing is saved, the
 *     flows of an idle instance are not started; flows changed during the drain
 *     outside of the drained ones get one more `preReload` (outside the lock,
 *     D-17), at most once (R-36)
 *  6. the slot is released; `runtime-deploy` is emitted by the reload
 *
 * The `preReload` hook - `RED.hooks.add("preReload", handler)` - may only delay
 * the reload: a rejection, an exception, `false` or the timeout are logged and
 * the reload goes on (R-20). The payload (frozen):
 *
 * @typedef PreReloadEvent
 * @type {object}
 * @property {string} rev - the revision that will be started
 * @property {string|null} activeRev - the running revision
 * @property {"full"|"diff"} type
 * @property {string[]|null} changedFlows - the ids of the flows (tabs and subflows)
 *     that are restarted; null when all flows are restarted
 * @property {boolean} credentialsChanged - computed: the credentials in storage
 *     differ from the running ones (not the flag of the notification)
 * @property {number} deadline - Date.now() + preReloadTimeout when the drain started
 * @property {AbortSignal} signal - aborted with the reason "stopping" (the runtime
 *     stops) or "superseded" (a deployment on this instance)
 * @module
 */

const health = require("../health");
const { events } = require("@node-red/util");

const DEFAULT_TIMEOUT = 1200000;
const DEFAULT_RETRY = { min: 1000, max: 60000, attempts: 10 };
const ON_EXHAUSTED = ["fail", "keepReady"];
const DEFAULT_MAX_STALE_TIME = 1800000;
// The longest delay of setTimeout
const MAX_TIMER = 2147483647;
// The errors of the configuration, never kept ready (R-47): they keep their
// code; any other error of reading storage is "storage_error"
// (invalid_json, empty_file: a corrupt flow or credentials file, see
// storage/localfilesystem/util.js)
const CONFIG_ERRORS = ["credentials_load_failed", "invalid_flows", "invalid_json", "empty_file"];
const NOTIFICATION_ID = "reload-failed";
// How long the editor shows the message about the recovery, ms
const RECOVERED_TIMEOUT = 10000;
const TYPES = ["full", "diff"];
const SLOT_NAME = "reload";
const SLOT_TTL = 60000;
// D-18, R-36: a read error or an incomplete configuration (a missing, empty or
// invalid flow file) rejects the read instead of reloading an empty configuration
const STRICT_READ = Object.freeze({ strict: true });

function isPositiveNumber(value) {
    return typeof value === "number" && isFinite(value) && value > 0;
}

function stateKey(info) {
    return info.state + "|" + info.reason + "|" + info.since + "|" + !!info.draining;
}

/**
 * Creates a reloader. The runtime uses the instance exported by this module;
 * the tests create separate instances.
 * @param {object} [deps] - the instance state, the deploy pipeline and the deploy
 *     lock (default: the modules of the runtime)
 */
function createReloader(deps) {
    deps = deps || {};
    const instanceState = deps.state || require("../state");
    const pipeline = deps.pipeline || require("./pipeline");
    const lock = deps.lock || require("./lock");

    let runtime = null;
    let log = null;
    let config = null;
    let registered = false;
    let stopped = false;
    let startupDone = false;
    let buffered = false;
    let running = false;
    let pending = false;
    // The retry timer fired while a cycle was running (#26): the retry is kept
    // apart from `pending` (a notification) so that the end of that cycle can
    // drop it - a success makes it obsolete, a failure schedules its own retry
    let retryQueued = false;
    // After the retries were exhausted ("failed"): the next cycle reloads even
    // when the revision is unchanged, so the instance can become ready again
    let forceNext = false;
    // Failed cycles (a failed read, reread or reload) since the last successful
    // cycle, counted against retry.attempts; reset only by cycleSucceeded() and
    // when the retries are exhausted - a notification does not reset it (#17)
    let failedCycles = 0;
    // The exponent of the retry delay (backoff); a notification resets it
    let delayAttempt = 0;
    // After the retries were exhausted: storage is read again every retry.max
    // until a read succeeds (the instance becomes ready again)
    let exhausted = false;
    let retryTimer = null;
    // R-47: the condition of the failed reload - {code, since, attempts, rev,
    // keepReady, staleDeadline, stale} - or null; the fact is in the instance state
    let condition = null;
    let staleTimer = null;
    let notified = false;
    // Failed cycles since the last successful one
    let totalFailures = 0;
    // The retry timer fired: the next failure may log an error (rate limit)
    let retryDue = false;
    let lastConditionLog = 0;
    // Date.now() of the first failed cycle of the current series of failures
    let failureSince = null;
    let lastStateKey = null;
    // Aborted by stop(): ends the waits (sleep) of the reloader
    let stopController = new AbortController();
    let unwatch = null;
    let unsubscribeState = null;
    // The running cycle: {controller, slot}
    let cycle = null;

    function readConfig(settings) {
        const deploy = (settings && settings.deploy) || {};
        const reload = (deploy.reload && typeof deploy.reload === "object") ? deploy.reload : {};
        const result = {
            watch: reload.watch === true,
            type: "full",
            preReloadTimeout: DEFAULT_TIMEOUT,
            concurrency: 0,
            // Z-16: invalid values are reported by health.init(), here 0 (off)
            unreadyGrace: health.resolveUnreadyGrace(settings).ms,
            retry: Object.assign({}, DEFAULT_RETRY, { onExhausted: "fail", maxStaleTime: DEFAULT_MAX_STALE_TIME })
        };
        if (reload.type !== undefined) {
            if (TYPES.indexOf(reload.type) !== -1) {
                result.type = reload.type;
            } else {
                log.warn(log._("reload.invalid-type", { value: String(reload.type) }));
            }
        }
        if (reload.preReloadTimeout !== undefined) {
            if (isPositiveNumber(reload.preReloadTimeout)) {
                result.preReloadTimeout = reload.preReloadTimeout;
            } else {
                log.warn(log._("reload.invalid-timeout", { value: String(reload.preReloadTimeout) }));
            }
        }
        if (reload.concurrency !== undefined) {
            // R-20: only a number of instances, no percentage
            if (Number.isInteger(reload.concurrency) && reload.concurrency >= 1) {
                result.concurrency = reload.concurrency;
            } else {
                log.warn(log._("reload.invalid-concurrency", { value: String(reload.concurrency) }));
            }
        }
        const retry = (reload.retry && typeof reload.retry === "object") ? reload.retry : {};
        ["min", "max"].forEach(function(key) {
            if (retry[key] !== undefined) {
                if (isPositiveNumber(retry[key])) {
                    result.retry[key] = retry[key];
                } else {
                    log.warn(log._("reload.invalid-retry", { key: key, value: String(retry[key]) }));
                }
            }
        });
        if (retry.attempts !== undefined) {
            if (Number.isInteger(retry.attempts) && retry.attempts >= 1) {
                result.retry.attempts = retry.attempts;
            } else {
                log.warn(log._("reload.invalid-retry", { key: "attempts", value: String(retry.attempts) }));
            }
        }
        if (retry.onExhausted !== undefined) {
            if (ON_EXHAUSTED.indexOf(retry.onExhausted) !== -1) {
                result.retry.onExhausted = retry.onExhausted;
            } else {
                log.warn(log._("reload.invalid-on-exhausted", { value: String(retry.onExhausted) }));
            }
        }
        if (retry.maxStaleTime !== undefined) {
            // 0: no limit
            if (typeof retry.maxStaleTime === "number" && isFinite(retry.maxStaleTime) && retry.maxStaleTime >= 0 && retry.maxStaleTime <= MAX_TIMER) {
                result.retry.maxStaleTime = retry.maxStaleTime;
            } else {
                log.warn(log._("reload.invalid-retry", { key: "maxStaleTime", value: String(retry.maxStaleTime) }));
            }
        }
        if (result.retry.max < result.retry.min) {
            result.retry.max = result.retry.min;
        }
        return result;
    }

    /**
     * @param {object} _runtime - the internal runtime api
     */
    function init(_runtime) {
        runtime = _runtime;
        log = runtime.log;
        registered = false;
        stopped = false;
        startupDone = false;
        buffered = false;
        running = false;
        pending = false;
        retryQueued = false;
        forceNext = false;
        failedCycles = 0;
        delayAttempt = 0;
        exhausted = false;
        retryTimer = null;
        condition = null;
        clearStaleTimer();
        notified = false;
        totalFailures = 0;
        retryDue = false;
        lastConditionLog = 0;
        failureSince = null;
        lastStateKey = null;
        stopController = new AbortController();
        unwatch = null;
        cycle = null;
        config = readConfig(runtime.settings);
    }

    /**
     * Registers the observer with the storage (`watchFlows`) - after the
     * storage and the coordination started and before the flows are read.
     * Without `deploy.reload.watch` nothing happens; a storage without
     * `watchFlows` only logs a warning.
     * @return {Promise} rejected when the storage rejects the registration (R-36)
     */
    async function register() {
        if (!config || !config.watch) {
            return;
        }
        const storage = runtime.storage;
        if (!storage || typeof storage.hasWatchFlows !== "function" || !storage.hasWatchFlows()) {
            log.warn(log._("reload.watch-not-supported"));
            return;
        }
        if (config.concurrency && isLocalCoordination()) {
            log.warn(log._("reload.concurrency-local", { concurrency: config.concurrency }));
            config.concurrency = 0;
        }
        let result;
        try {
            result = await storage.watchFlows(onNotification);
        } catch (err) {
            log.error(log._("reload.watch-failed", { message: (err && err.message) || String(err) }));
            throw err;
        }
        unwatch = typeof result === "function" ? result : null;
        registered = true;
        lastStateKey = stateKey(instanceState.get());
        unsubscribeState = instanceState.onChange(onStateChange);
        log.info(log._("reload.watching", { type: config.type }));
    }

    function isLocalCoordination() {
        const coordination = runtime.coordination;
        if (!coordination || typeof coordination.claimSlot !== "function") {
            return true;
        }
        try {
            return !coordination.info || coordination.info().local !== false;
        } catch (err) {
            return true;
        }
    }

    /**
     * The end of the first start of the flows (also a failed one): the
     * buffered notifications are handled now.
     */
    function startupComplete() {
        startupDone = true;
        if (buffered && registered && !stopped) {
            buffered = false;
            schedule();
        }
    }

    /**
     * Stops observing: the running cycle is aborted ("stopping") and the
     * storage observer is unregistered.
     */
    async function stop() {
        stopped = true;
        clearRetry();
        clearStaleTimer();
        if (!stopController.signal.aborted) {
            stopController.abort("stopping");
        }
        if (cycle) {
            abortCycle("stopping");
        }
        if (unsubscribeState) {
            unsubscribeState();
            unsubscribeState = null;
        }
        const wasRegistered = registered;
        registered = false;
        if (wasRegistered && unwatch) {
            const fn = unwatch;
            unwatch = null;
            try {
                await fn();
            } catch (err) {
                log.debug("reload: unwatch failed: " + ((err && err.message) || err));
            }
        }
    }

    // The callback given to watchFlows
    function onNotification(notification) {
        try {
            if (stopped || !registered) {
                log.debug("reload: notification ignored - not watching");
                return;
            }
            // The `credentialsChanged` flag of the notification is a hint to read
            // storage, which every notification does (#2): whether the credentials
            // changed is decided by comparing them (runCycle)
            // A new notification resets the retry delay, not the count of the
            // failed cycles (#17): notifications that keep coming must not stop
            // retry.attempts from being reached
            delayAttempt = 0;
            clearRetry();
            if (!startupDone) {
                buffered = true;
                return;
            }
            schedule();
        } catch (err) {
            log.debug("reload: notification failed: " + ((err && err.message) || err));
        }
    }

    function onStateChange(info) {
        // R-47: instance:state is also emitted when only the condition `reload`
        // changes - the cycle reacts to changes of the state only. For example
        // the deploy pipeline clears the condition (clearReloadFailed) in the
        // state "deploying" with previous "reloadPending": without this filter
        // the cycle would be "superseded" a second time (a second log and abort).
        const key = stateKey(info);
        const stateChanged = key !== lastStateKey;
        lastStateKey = key;
        if (condition && !info.reload) {
            // Cleared outside of the reloader (a successful local deployment)
            endCondition("deploy");
        }
        if (!stateChanged || !cycle) {
            return;
        }
        if (info.state === "stopping") {
            abortCycle("stopping");
        } else if (info.state === "deploying" && info.previous === "reloadPending") {
            // A deployment on this instance supersedes the pending reload (E-02 T5)
            log.info(log._("reload.superseded"));
            abortCycle("superseded");
        }
    }

    function abortCycle(reason) {
        if (cycle && !cycle.controller.signal.aborted) {
            cycle.controller.abort(reason);
        }
    }

    function schedule() {
        if (running) {
            pending = true;
            return;
        }
        running = true;
        (async function() {
            try {
                // retryQueued: a retry that fired during the cycle and was not
                // dropped by its success or failure. Today every path that ends
                // a cycle without a result sets `pending` itself, so this is a
                // safety net for a future path that does not (#26)
                do {
                    pending = false;
                    retryQueued = false;
                    await runCycle();
                } while ((pending || retryQueued) && !stopped);
            } catch (err) {
                log.warn(log._("reload.failed", { message: (err && err.message) || String(err) }));
            } finally {
                running = false;
            }
        })();
    }

    // A timer that does not keep the process alive
    function unrefTimer(timer) {
        if (timer && typeof timer.unref === "function") {
            timer.unref();
        }
        return timer;
    }

    // Resolves after `ms`, when `signal` is aborted or when the reloader stops
    function sleep(ms, signal) {
        const signals = [stopController.signal];
        if (signal) {
            signals.push(signal);
        }
        return new Promise(function(resolve) {
            if (signals.some(function(s) { return s.aborted })) {
                return resolve();
            }
            const timer = unrefTimer(setTimeout(done, ms));
            function done() {
                clearTimeout(timer);
                signals.forEach(function(s) { s.removeEventListener("abort", done) });
                resolve();
            }
            signals.forEach(function(s) { s.addEventListener("abort", done) });
        });
    }

    function clearRetry() {
        if (retryTimer) {
            clearTimeout(retryTimer);
            retryTimer = null;
        }
    }

    // Schedules the next cycle after `ms`; replaces a pending retry
    function scheduleRetry(ms) {
        clearRetry();
        retryTimer = unrefTimer(setTimeout(function() {
            retryTimer = null;
            retryDue = true;
            if (running) {
                // A cycle is running: the retry is not an immediate extra cycle
                // (#26) - the end of the cycle decides (see cycleSucceeded and
                // readFailed); a cycle that ends without a result keeps it.
                // Today every such path sets `pending` itself, so keeping the
                // retry here is a safety net for a future no-result path
                retryQueued = true;
                return;
            }
            schedule();
        }, ms));
    }

    function backoff(attempt) {
        return Math.min(config.retry.max, config.retry.min * Math.pow(2, Math.max(0, attempt - 1)));
    }

    // The cycle succeeded (the reload was applied or the revision is unchanged):
    // the series of failures ends (#17). A read of step 2 alone is not a success -
    // the reread under the lock or the reload itself may still fail. A retry
    // scheduled by an earlier failed cycle is obsolete now and is cancelled (#26),
    // also when its timer fired during this cycle (retryQueued): retries are
    // scheduled by readFailed() only, so no other retry is lost.
    function cycleSucceeded() {
        clearRetry();
        retryQueued = false;
        failedCycles = 0;
        delayAttempt = 0;
        totalFailures = 0;
        failureSince = null;
        exhausted = false;
    }

    function getActiveRev() {
        const active = runtime.flows.getFlows();
        return active ? active.rev : null;
    }

    function errorCode(err, fromStorage) {
        const code = err && typeof err.code === "string" ? err.code : null;
        if (CONFIG_ERRORS.indexOf(code) !== -1) {
            return code;
        }
        // A failure of the reload itself (the credentials, the stop of the flows)
        // is not an error of reading storage; raw codes do not leak out (R-47)
        return fromStorage ? "storage_error" : "reload_failed";
    }

    // The condition `reload` (R-47) in the instance state; the revision in
    // storage is the last one seen that differs from the running one
    function pushCondition() {
        instanceState.markReloadFailed({
            error: { code: condition.code },
            since: condition.since,
            attempts: condition.attempts,
            activeRev: getActiveRev(),
            rev: condition.rev,
            keepReady: condition.keepReady,
            staleDeadline: condition.staleDeadline,
            stale: condition.stale
        });
    }

    function clearStaleTimer() {
        if (staleTimer) {
            clearTimeout(staleTimer);
            staleTimer = null;
        }
    }

    function armStaleTimer() {
        clearStaleTimer();
        if (!condition || !condition.keepReady || condition.staleDeadline === null || condition.stale || stopped) {
            return;
        }
        staleTimer = unrefTimer(setTimeout(onStale, Math.max(0, condition.staleDeadline - Date.now())));
    }

    // maxStaleTime passed: /ready is 503 (health.js); the listeners learn it from the event
    function onStale() {
        staleTimer = null;
        if (!condition || stopped) {
            return;
        }
        if (Date.now() < condition.staleDeadline) {
            return armStaleTimer();
        }
        condition.stale = true;
        log.error(log._("reload.stale", { code: condition.code, since: new Date(condition.since).toISOString(), limit: config.retry.maxStaleTime, rev: getActiveRev() }));
        pushCondition();
        if (notified) {
            // the same notification (the editor updates it): no longer ready
            events.emit("runtime-event", {
                id: NOTIFICATION_ID,
                payload: { type: "error", error: "reload_stale", text: "notification.warnings.reload_stale", code: condition.code, since: new Date(condition.since).toISOString() },
                retain: true
            });
        }
    }

    function notifyEditor() {
        notified = true;
        events.emit("runtime-event", {
            id: NOTIFICATION_ID,
            payload: { type: "warning", error: "reload_failed", text: "notification.warnings.reload_failed", code: condition.code, since: new Date(condition.since).toISOString() },
            retain: true
        });
    }

    // Removes the notification of the editor and the retained entry (no payload)
    function clearEditorNotification() {
        if (notified) {
            notified = false;
            events.emit("runtime-event", { id: NOTIFICATION_ID, retain: false });
        }
    }

    // Recovery: the notification of the editor turns into a message that
    // disappears after a while; it is not retained (a new editor shows nothing)
    function notifyRecovered() {
        if (notified) {
            notified = false;
            events.emit("runtime-event", {
                id: NOTIFICATION_ID,
                payload: { type: "success", text: "notification.warnings.reload_recovered", timeout: RECOVERED_TIMEOUT },
                retain: false
            });
        }
    }

    // The condition is over: timer, notification and log; the state is cleared
    // by the caller (or was cleared already)
    function endCondition(reason) {
        const ended = condition;
        condition = null;
        failureSince = null;
        clearStaleTimer();
        notifyRecovered();
        totalFailures = 0;
        log.info(log._("reload.recovered", { reason: reason, code: ended.code, since: new Date(ended.since).toISOString(), duration: Date.now() - ended.since }));
    }

    // Storage was read successfully or a reload / deployment succeeded
    function clearCondition(reason) {
        if (!condition) {
            return;
        }
        endCondition(reason);
        instanceState.clearReloadFailed();
    }

    // The retries were exhausted (or, with a running condition, the kind of the
    // failure changed): default - "failed" and a forced reload (R-36); keepReady
    // with a read error of storage - the lifecycle state stays (R-47)
    function applyExhausted(code, message, rev) {
        if (config.retry.onExhausted !== "keepReady") {
            // "fail" (the default): R-36 exactly as before R-47 - no condition,
            // no event, no log, no notification
            forceNext = true;
            instanceState.fail([{ code: "storage_error", message: message }], "storage-error");
            return;
        }
        const keep = code === "storage_error";
        const wasKept = !!(condition && condition.keepReady);
        // The first failed read of the series, not the end of the retries
        const since = condition ? condition.since : (failureSince !== null ? failureSince : Date.now());
        const next = {
            code: code,
            since: since,
            attempts: totalFailures,
            rev: rev === undefined ? (condition ? condition.rev : null) : rev,
            keepReady: keep,
            staleDeadline: keep && config.retry.maxStaleTime > 0 ? since + config.retry.maxStaleTime : null,
            stale: keep && !!(condition && condition.stale)
        };
        if (keep) {
            condition = next;
            pushCondition();
            if (!wasKept) {
                notifyEditor();
            }
            armStaleTimer();
            lastConditionLog = Date.now();
            log.error(log._("reload.keep-ready", { code: code, attempts: totalFailures, rev: getActiveRev(), message: message }));
            return;
        }
        clearStaleTimer();
        clearEditorNotification();
        if (wasKept) {
            log.error(log._("reload.not-kept-ready", { code: code, message: message }));
        }
        forceNext = true;
        // "failed" first, then the condition: a listener never sees a ready
        // instance with the condition keepReady false in between. The reloader's
        // own condition is set after fail(), so the event of fail() is not taken
        // for a clear of the condition outside of the reloader
        instanceState.fail([{ code: "storage_error", message: message }], "storage-error");
        condition = next;
        pushCondition();
    }

    // A failed cycle - a failed read of storage (step 2 or the reread under the
    // lock) or a failed reload (#17): retry with an exponential delay; after
    // retry.attempts failed cycles in a row the instance state is "failed"
    // (D-18, R-20, R-36) - the running flows are not stopped - and the cycle is
    // repeated every retry.max until one succeeds. With onExhausted "keepReady"
    // the state is not changed after a read error of storage (R-47).
    // `opts.fromStorage` (default true): the error comes from reading storage;
    // `opts.rev`: the revision in storage the reload was about
    function readFailed(err, opts) {
        if (stopped) {
            return;
        }
        opts = opts || {};
        // This failure schedules its own retry with the proper delay: a retry
        // that fired during the cycle must not start an immediate extra cycle (#26)
        retryQueued = false;
        const message = (err && err.message) || String(err);
        const code = errorCode(err, opts.fromStorage !== false);
        totalFailures++;
        if (failureSince === null) {
            failureSince = Date.now();
        }
        if (exhausted && !condition && code !== "storage_error" && instanceState.get().state !== "failed") {
            // The retries were exhausted earlier and the instance has recovered
            // since (a local deployment ended the condition), and now the cycle
            // fails with a configuration error or a failed reload: a new series
            // is counted, it can exhaust the retries again (#17). A pure read
            // error of storage keeps the behaviour of the exhausted state below.
            exhausted = false;
            failedCycles = 0;
            delayAttempt = 0;
            totalFailures = 1;
            failureSince = Date.now();
        }
        if (exhausted) {
            log.debug("reload: still failing after the retries were exhausted: " + message);
            const keep = config.retry.onExhausted === "keepReady" && code === "storage_error";
            if (!condition) {
                // The condition ended with a local deployment, storage is still
                // unreadable: with keepReady it is reported again (default: as before)
                if (keep) {
                    applyExhausted(code, message, opts.rev);
                }
            } else {
                if (condition.keepReady && !keep) {
                    applyExhausted(code, message, opts.rev);
                } else {
                    condition.attempts = totalFailures;
                    condition.code = code;
                    if (opts.rev !== undefined) {
                        condition.rev = opts.rev;
                    }
                    pushCondition();
                    if (condition.keepReady && (retryDue || Date.now() - lastConditionLog >= config.retry.max)) {
                        lastConditionLog = Date.now();
                        log.error(log._("reload.still-failing", { code: code, attempts: totalFailures, since: new Date(condition.since).toISOString(), rev: getActiveRev(), message: message }));
                    }
                }
            }
            retryDue = false;
            scheduleRetry(config.retry.max);
            return;
        }
        failedCycles++;
        delayAttempt++;
        log.warn(log._("reload.read-failed", { message: message, attempt: failedCycles, attempts: config.retry.attempts }));
        if (failedCycles >= config.retry.attempts) {
            // keepReady with a read error of storage: only the keep-ready error is
            // logged (applyExhausted) - "the instance is not ready" would contradict it
            if (!(config.retry.onExhausted === "keepReady" && code === "storage_error")) {
                log.error(log._("reload.retries-exhausted", { attempts: failedCycles }));
            }
            failedCycles = 0;
            delayAttempt = 0;
            exhausted = true;
            retryDue = false;
            applyExhausted(code, message, opts.rev);
            scheduleRetry(config.retry.max);
            return;
        }
        scheduleRetry(backoff(delayAttempt));
    }

    // Waits until a running operation under the deploy lock has completed
    async function waitForOperation() {
        await lock.runExclusive(async function() {});
        await sleep(config.retry.min);
    }

    async function acquireSlot(signal) {
        let failures = 0;
        while (!signal.aborted) {
            try {
                const claim = await runtime.coordination.claimSlot(SLOT_NAME, config.concurrency, SLOT_TTL);
                if (claim) {
                    return claim;
                }
                log.debug("reload: waiting for a reload slot");
                failures = 0;
                await sleep(config.retry.min, signal);
            } catch (err) {
                // R-20: no connection to the coordinator - the reload waits,
                // the old configuration keeps running
                failures++;
                log.warn(log._("reload.slot-claim-failed", { message: (err && err.message) || String(err) }));
                await sleep(backoff(failures), signal);
            }
        }
        return null;
    }

    function holdSlot(claim) {
        if (!claim || typeof claim.renew !== "function") {
            return null;
        }
        const timer = setInterval(function() {
            Promise.resolve().then(function() { return claim.renew(SLOT_TTL) }).then(function(kept) {
                if (kept === false) {
                    log.warn(log._("reload.slot-lost"));
                }
            }, function(err) {
                log.debug("reload: slot renew failed: " + ((err && err.message) || err));
            });
        }, Math.floor(SLOT_TTL / 3));
        if (timer.unref) {
            timer.unref();
        }
        return timer;
    }

    function releaseSlot(current) {
        if (!current || !current.slot) {
            return;
        }
        if (current.renewTimer) {
            clearInterval(current.renewTimer);
        }
        const claim = current.slot;
        current.slot = null;
        Promise.resolve().then(function() {
            return typeof claim.release === "function" ? claim.release() : undefined;
        }).catch(function(err) {
            log.debug("reload: slot release failed: " + ((err && err.message) || err));
        });
    }

    // The preReload hook with the limit; resolves when the reload may go on
    function drain(info) {
        const hooks = runtime.hooks;
        if (!hooks || !hooks.has("preReload")) {
            return Promise.resolve();
        }
        const remaining = info.deadline - Date.now();
        if (remaining <= 0) {
            log.warn(log._("reload.hook-timeout", { timeout: config.preReloadTimeout }));
            return Promise.resolve();
        }
        const payload = Object.freeze({
            rev: info.rev,
            activeRev: info.activeRev,
            type: config.type,
            changedFlows: info.changedFlows ? Object.freeze(info.changedFlows.slice()) : null,
            credentialsChanged: !!info.credentialsChanged,
            deadline: info.deadline,
            signal: info.signal
        });
        return new Promise(function(resolve) {
            let finished = false;
            const timer = unrefTimer(setTimeout(function() {
                if (!finished) {
                    log.warn(log._("reload.hook-timeout", { timeout: config.preReloadTimeout }));
                }
                finish();
            }, remaining));
            function finish() {
                if (!finished) {
                    finished = true;
                    clearTimeout(timer);
                    info.signal.removeEventListener("abort", finish);
                    resolve();
                }
            }
            info.signal.addEventListener("abort", finish);
            let result;
            try {
                result = hooks.trigger("preReload", payload);
            } catch (err) {
                result = Promise.reject(err);
            }
            Promise.resolve(result).then(function(value) {
                if (value === false && !finished) {
                    log.error(log._("reload.hook-failed", { message: "false" }));
                }
                finish();
            }, function(err) {
                if (!finished && !info.signal.aborted) {
                    log.error(log._("reload.hook-failed", { message: (err && err.message) || String(err) }));
                }
                finish();
            });
        });
    }

    async function runCycle() {
        if (stopped) {
            return;
        }
        const force = forceNext;

        // Step 2: read storage (no lock) and compare the revisions
        let loaded;
        try {
            loaded = await runtime.storage.getFlows(STRICT_READ);
        } catch (err) {
            readFailed(err);
            return;
        }
        // #2: the credentials are compared by the digest of their decrypted content;
        // nothing is loaded (the cache and the key stay as they are). A key that does
        // not decrypt them is a configuration error (credentials_load_failed)
        let credentialsChanged;
        try {
            credentialsChanged = runtime.flows.credentialsChanged(loaded);
        } catch (err) {
            readFailed(err, { fromStorage: false, rev: loaded.rev });
            return;
        }
        const activeRev = getActiveRev();
        if (loaded.rev === activeRev && !credentialsChanged && !force) {
            log.debug("reload: revision " + loaded.rev + " is already active");
            cycleSucceeded();
            // R-47 keepReady: storage is readable again and holds the running
            // revision - no drain, no preReload, no restart
            clearCondition("unchanged");
            return;
        }

        // Step 3: "reloadPending" - no lock, no token
        if (!instanceState.markReloadPending({ reason: "reload" })) {
            // Another operation runs (a deployment, POST /flows/state): try
            // again once it has completed
            if (!stopped) {
                await waitForOperation();
                pending = true;
            }
            return;
        }
        const reloadType = (config.type === "diff" && !credentialsChanged) ? "diff" : "full";
        let drained = reloadType === "diff" ? runtime.flows.getChangedFlows(loaded) : null;
        const current = cycle = { controller: new AbortController(), slot: null, renewTimer: null };
        const signal = current.controller.signal;
        try {
            if (config.concurrency) {
                current.slot = await acquireSlot(signal);
                current.renewTimer = holdSlot(current.slot);
            }
            if (signal.aborted) {
                return;
            }

            // Step 4: drain - /ready 503 from now on
            instanceState.markDraining();
            const deadline = Date.now() + config.preReloadTimeout;
            // Z-16: /ready has answered 503 since the line above; the flows are not
            // stopped before the grace has passed, counted inside preReloadTimeout
            const grace = Math.min(config.unreadyGrace, config.preReloadTimeout);
            const graceWait = grace > 0 ? sleep(grace, signal) : null;
            if (graceWait) {
                log.info(log._("reload.unready-grace", { grace: grace }));
            }
            await Promise.all([
                drain({ rev: loaded.rev, activeRev: activeRev, changedFlows: drained, credentialsChanged: credentialsChanged, deadline: deadline, signal: signal }),
                graceWait
            ]);

            // Step 5: under the deploy lock - read storage again and reload
            let extraRound = false;
            while (!signal.aborted) {
                let decision = null;
                const result = await pipeline.deploy({
                    type: "reload",
                    source: "storage",
                    reread: async function() {
                        decision = await reread({ signal: signal, drained: drained, extraRound: extraRound, force: force, reloadType: reloadType });
                        return decision;
                    }
                });
                if (result && result.rev !== undefined) {
                    forceNext = false;
                    cycleSucceeded();
                    // Storage works again, also when the start of the new flows fails (R-47)
                    clearCondition("reload");
                    log.info(log._("reload.reloaded", { rev: result.rev, type: decision.reloadType }));
                    log.audit({ event: "flows.reload", source: "storage", rev: result.rev, type: decision.reloadType });
                    return;
                }
                if (!decision || decision.skip) {
                    // superseded, aborted or nothing to do any more
                    if (decision && decision.skip === "unchanged") {
                        log.debug("reload: storage unchanged after the drain");
                        cycleSucceeded();
                        clearCondition("unchanged");
                    } else if (result && result.skipped === "superseded") {
                        // Another operation (POST /flows/state) left "reloadPending"
                        current.superseded = true;
                    }
                    return;
                }
                if (decision.error) {
                    readFailed(decision.error, { rev: loaded.rev });
                    return;
                }
                // D-17: flows changed during the drain - one more preReload for
                // them, outside the lock, within the remaining limit
                extraRound = true;
                drained = decision.extra === null ? null : drained.concat(decision.extra);
                await drain({ rev: decision.fresh.rev, activeRev: getActiveRev(), changedFlows: decision.extra, credentialsChanged: credentialsChanged, deadline: deadline, signal: signal });
            }
        } catch (err) {
            // The reload failed before the flows were changed (for example the
            // credentials could not be loaded): the state is restored by the pipeline
            readFailed(err, { fromStorage: false, rev: loaded.rev });
        } finally {
            releaseSlot(current);
            if (cycle === current) {
                cycle = null;
            }
            if (!stopped && (current.superseded || signal.reason === "superseded")) {
                // The cycle was superseded by an operation that may not have
                // saved to storage (POST /flows/state, a failed deployment):
                // one more cycle compares the revision in storage with the
                // active one and reloads when they differ (no lost reload)
                log.debug("reload: superseded - checking the revision in storage again");
                pending = true;
            }
        }
    }

    // Step 5, called by the pipeline under the deploy lock in "reloadPending"
    async function reread(opts) {
        if (opts.signal.aborted) {
            return { skip: "aborted" };
        }
        let fresh;
        try {
            fresh = await runtime.storage.getFlows(STRICT_READ);
        } catch (err) {
            // T7b: back to the state before the cycle, the flows keep running
            instanceState.cancelPending();
            return { error: err };
        }
        let credentialsChanged;
        try {
            credentialsChanged = runtime.flows.credentialsChanged(fresh);
        } catch (err) {
            // The credentials of the newest revision cannot be decrypted (#2): as
            // a failed read, back to the state before the cycle
            instanceState.cancelPending();
            return { error: err };
        }
        if (fresh.rev === getActiveRev() && !credentialsChanged && !opts.force) {
            instanceState.cancelPending();
            return { skip: "unchanged" };
        }
        // The credentials changed during the drain: the diff does not see them,
        // so this is a full reload
        const reloadType = credentialsChanged ? "full" : opts.reloadType;
        if (reloadType === "diff" && opts.drained !== null) {
            const now = runtime.flows.getChangedFlows(fresh);
            const extra = now === null ? null : now.filter(function(id) { return opts.drained.indexOf(id) === -1 });
            if (extra === null || extra.length > 0) {
                if (!opts.extraRound) {
                    log.warn(log._("reload.changed-during-drain", { flows: extra === null ? "*" : extra.join(", ") }));
                    return { extra: extra, fresh: fresh };
                }
                // R-36: at most one more round - reload the newest revision
                log.warn(log._("reload.changed-after-extra-drain", { flows: extra === null ? "*" : extra.join(", ") }));
            }
        }
        return { apply: fresh, reloadType: reloadType, credentialsChanged: credentialsChanged };
    }

    return {
        init: init,
        register: register,
        startupComplete: startupComplete,
        stop: stop
    };
}

module.exports = createReloader();
module.exports.createReloader = createReloader;
